const tocEntries = files.map((f) => {
  const anchor = f.path.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
  return `${f.num}. [\`${f.path}\`](#${anchor}) — *${f.desc}*`;
});

const sections = [headerSection + '\n' + tocEntries.join('\n')];

for (const f of files) {
  const fullPath = path.join(projectDir, f.path);
  if (!fs.existsSync(fullPath)) {
    console.warn(`File missing: ${f.path}`);
    continue;
  }
  const code = fs.readFileSync(fullPath, 'utf8');
  const anchor = f.path.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
  const sectionMd = `## ${f.num}. \`${f.path}\` <a id="${anchor}"></a>\n\n**Description:** ${f.desc}  \n**File Path:** \`sreenidhi-express/${f.path}\`  \n\n\`\`\`${f.lang}\n${code}\n\`\`\``;
  sections.push(sectionMd);
}

// Join sections with clean markdown separators (NEVER uses String.prototype.replace)
const finalDocument = sections.join('\n\n---\n\n') + '\n';

fs.writeFileSync(reviewFile, finalDocument, 'utf8');
fs.writeFileSync(mfFile, finalDocument, 'utf8');

console.log(`Compilation successful! Generated ${reviewFile} (${(finalDocument.length / 1024).toFixed(1)} KB, ${files.length} source files bundled cleanly without $' regex corruption).`);
